exploreUrl:
@js:
var sort=[];
push=(title,url,type,size)=>sort.push({
    "title": title,
    "url": url?url:"",
    "style": {
      "layout_flexGrow": type,
      "layout_flexBasisPercent": size,
    }
  });

bd=["必读榜","潜力榜","完本榜",
"更新榜","搜索榜","评论榜"];
pd=[["男频","1"],
	["女频","2"]].map([title,id]=>{
push(title+'榜单', null, 1, 1);
		bd.map((title,index)=>{			
		  	url= `/module/rank?type=${index+1}&channel=${id}&page={{page}}`; 
				push(title, url, 1, 0.25);										
			});
	});

book=[["男频",
[["玄幻","lejRej"],["都市","mbk5ez"],["武侠","nel5aK"],["仙侠","vbmOeY"],["军事","penRe7"],["历史","xbojag"],["游戏","mep2bM"],["科幻","zbq2dp"],["轻小说","YerEdO"]]],
	 ["女频",
[["现代言情","9avmeG"],["古代言情","DdwRb1"],["幻想言情","7ax9by"],["青春校园","Pdy7aQ"],["唯美纯爱","kazYeJ"],["同人衍生","9aAOdv"]]]].map([tit1,category]=>{
	 		[["连载","0"],["完结","1"]].map([tit2,id]=>{  
	    push(tit1+'•'+tit2, null, 1, 1);   
     category.map([title,cid]=>{	    
	url= `/novel?isComplete=${id}&sort=1&page={{page}}&categoryId=${cid}`;	
			 	push(title, url, 1, 0.25);
        });
      });
  });

JSON.stringify(sort)

