"id=")===-1){htmlContent=java.ajax(url);cache.put(cacheKey,htmlContent)}let browserConfig={"expandedCornersRadius":20,"dismissOnTouchOutside":true,"isDraggable":true,"shouldDimBackground":true,"backgroundDimAmount":0.5,"hardwareAccelerated":true,"isNestedScrollingEnabled":true,"isGestureInsetBottomIgnored":true,"setFitToContents":true,"isHideable":true,"heightPercentage":0.8};java.showBrowser(url,htmlContent,"window.java=java;",JSON.stringify(browserConfig))}function createChapter(url,svg){var encodedSvg=this.java.base64Encode(svg);encodedSvg=`data:image/svg+xml;base64,${encodedSvg},{"click":"showChapter('${mw+url}' )","style":"FULL"}`;return`<img src="${encodedSvg}">`}


